#' Overidentification and Endogeneity
#'
#' 
#' @param data .
#' @param outcome .
#' @param endog .
#' @param instruments .
#' @param controls .
#' @param absorb .
#' @param cluster .
#' @param weights .
#' @param vce .
#' @param small .
#' @param suspects .
#' @param endogTest .
#' @param showEach .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$overid} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ctest} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$endog} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$each} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$overid$asDF}
#'
#' \code{as.data.frame(results$overid)}
#'
#' @export
ivover <- function(
    data,
    outcome,
    endog,
    instruments,
    controls,
    absorb,
    cluster,
    weights,
    vce = "classical",
    small = TRUE,
    suspects,
    endogTest,
    showEach = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ivover requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(endog)) endog <- jmvcore::resolveQuo(jmvcore::enquo(endog))
    if ( ! missing(instruments)) instruments <- jmvcore::resolveQuo(jmvcore::enquo(instruments))
    if ( ! missing(controls)) controls <- jmvcore::resolveQuo(jmvcore::enquo(controls))
    if ( ! missing(absorb)) absorb <- jmvcore::resolveQuo(jmvcore::enquo(absorb))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if ( ! missing(weights)) weights <- jmvcore::resolveQuo(jmvcore::enquo(weights))
    if ( ! missing(suspects)) suspects <- jmvcore::resolveQuo(jmvcore::enquo(suspects))
    if ( ! missing(endogTest)) endogTest <- jmvcore::resolveQuo(jmvcore::enquo(endogTest))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(endog), endog, NULL),
            `if`( ! missing(instruments), instruments, NULL),
            `if`( ! missing(controls), controls, NULL),
            `if`( ! missing(absorb), absorb, NULL),
            `if`( ! missing(cluster), cluster, NULL),
            `if`( ! missing(weights), weights, NULL),
            `if`( ! missing(suspects), suspects, NULL),
            `if`( ! missing(endogTest), endogTest, NULL))


    options <- ivoverOptions$new(
        outcome = outcome,
        endog = endog,
        instruments = instruments,
        controls = controls,
        absorb = absorb,
        cluster = cluster,
        weights = weights,
        vce = vce,
        small = small,
        suspects = suspects,
        endogTest = endogTest,
        showEach = showEach,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- ivoverClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

